declare global {
    interface String {
        trimBeginChars(chars: string, atBegin?: boolean): string;
    }
}
/**
 * 截断字符串前面的字符
 *
 *  "abc123xyz".trimBeginChars("abc") == "123xyz"
 *
 * @param chars
 * @returns {string}
 */
declare function trimBeginChars(str: string, chars: string, atBeing?: boolean): string;

export { trimBeginChars };
